insert into public.site_content(key,value) values
($q$heroKicker$q$,$q$Cortina aberta desde 2005$q$),
($q$heroText$q$,$q$O movimento de grupos, artistas e produtores que mantém a cena teatral da cidade acesa: espetáculos, leituras, oficinas e festivais.$q$),
($q$heroBtn1$q$,$q$Ver a programação$q$),
($q$heroBtn2$q$,$q$Ler nossa história$q$),
